bus = SMBus(1)
climate = Bmp280(bus)
lcd = Lcd(bus)
eye = LightSensor(18, charge_time_limit=0.1)
fan = OutputDevice(27)
lamp = PWMLED(12)
HOT, COOL, DIM = 28.0, 26.0, 0.5

started = monotonic()
last_log = -2.0
print('time,temp,light,fan,lamp')
