        d = self.bus.read_i2c_block_data(self.address, 0xF7, 6)
        raw_p = (d[0] << 12) | (d[1] << 4) | (d[2] >> 4)
        raw_t = (d[3] << 12) | (d[4] << 4) | (d[5] >> 4)
        t1, t2, t3 = self.t
        a = (raw_t / 16384 - t1 / 1024) * t2
        b = (raw_t / 131072 - t1 / 8192) ** 2 * t3
